use strict;
use warnings;

my $ROOT = '/bench/repo';
my $MOD = 'github.com/usememos/memos';

my %decls;
my %calls;

my @all_go = split /\n/, `find '$ROOT' -name '*.go' 2>/dev/null`;

sub rel($) {
    my ($p) = @_;
    $p =~ s/^\Q$ROOT\E\/?//;
