            (my $local = $path) =~ s/.*\///;
            $imports{$local} = $path;
        } elsif (defined $3) {
            $imports{$3} = $4;
        } elsif (defined $1) {
            my $block = $1;
            while ($block =~ /(?:(\w+)\s+)?"([^"]+)"/g) {
                my ($alias, $path) = ($1, $2);
                $alias //= ($path =~ s/.*\///r);
                $imports{$alias} = $path;
            }
        }
    }

    my $pkgpath = pkgpath_from_rel($rel);
    my $full_pkgpath = "$MOD/" . $rel;
    $full_pkgpath =~ s{/[^/]+$}{};

    pos($clean) = 0;
    while ($clean =~ /^func\s+(?:\(([^)]*)\)\s+)?(\w+)\s*\(/gm) {
        my ($recv, $name) = ($1, $2);
        my $pos = pos($clean);
        my $prefix = substr($clean, 0, $pos);
        my $line_num = ($prefix =~ tr/\n//) + 1;

        my $recv_type = '';
        if (defined $recv && $recv ne '') {
            if ($recv =~ /\*\s*([\w\.]+)/) { $recv_type = $1; }
            elsif ($recv =~ /([\w\.]+)\s*$/) { $recv_type = $1; }
            $recv_type =~ s/^.*\.//;
        }

        if ($pkgpath && $rel =~ /^internal\//) {
            my $key = decl_key($pkgpath, $name, $recv_type);
            unless (exists $decls{$key}) {
                my $sym = $recv_type ? "($recv_type).$name" : $name;
                $decls{$key} = {
                    key => $key, file => $rel, line => $line_num, sym => $sym,
                    pkgpath => $pkgpath, name => $name, recv => $recv_type,
                    is_test => is_test_file($rel),
                };
            }
        }
    }

    return {
        file => $rel, pkg => $pkg, pkgpath => $full_pkgpath,
        imports => \%imports, is_test => is_test_file($rel), clean => $clean,
    };
