my %pkg_methods;
for my $d (values %decls) {
    if ($d->{recv}) {
        $pkg_methods{$d->{pkgpath}}{"$d->{recv}|$d->{name}"} = 1;
    }
}

sub resolve_func_call($$$) {
    my ($info, $pkg_alias, $func_name) = @_;
    if (defined $pkg_alias) {
        my $path = $info->{imports}{$pkg_alias};
        return undef unless defined $path && $path =~ m{^\Q$MOD/internal\E(/|$)};
        my $key = decl_key($path, $func_name, '');
        return $key if exists $decls{$key};
        return undef;
    }
    my $pp = pkgpath_from_rel($info->{file});
    if ($pp) {
        my $key = decl_key($pp, $func_name, '');
        return $key if exists $decls{$key};
    }
    if ($info->{pkgpath} =~ m{^\Q$MOD/internal\E(/|$)}) {
        my $key = decl_key($info->{pkgpath}, $func_name, '');
        return $key if exists $decls{$key};
    }
    return undef;
}

sub record_call($$$$) {
    my ($dk, $info, $caller_name, $caller_recv) = @_;
    return unless defined $dk && exists $decls{$dk};
    my $caller_id = "$info->{pkgpath}|$caller_recv|$caller_name|$info->{file}";
    push @{ $calls{$dk} }, {
        caller_id => $caller_id,
        caller_file => $info->{file},
        caller_test => $info->{is_test},
