sub infer_var_types($) {
    my ($body) = @_;
    my %types;
    while ($body =~ /\b(\w+)\s*:?=\s*(?:&|\*)?([\w\.]+)\{/g) {
        my ($v, $t) = ($1, $2); $t =~ s/^.*\.//; $types{$v} = $t;
    }
    while ($body =~ /\b(\w+)\s*:?=\s*(?:&|\*)?([\w\.]+)\(/g) {
        my ($v, $t) = ($1, $2);
        next if $t =~ /^(make|new|append|len|cap|delete|close|panic|recover|print|println)$/;
        $t =~ s/^.*\.//; $types{$v} = $t;
    }
    while ($body =~ /(?:^|[,\s])(\w+)\s+(?:\*([\w\.]+)|([\w\.]+))/gm) {
        my ($v, $tp, $t) = ($1, $2, $3); $t //= $tp; $t =~ s/^.*\.//; $types{$v} = $t;
    }
    return \%types;
}

sub resolve_method($$$$) {
    my ($info, $var, $method, $var_types) = @_;
    my $rtype = $var_types->{$var};
    if ($rtype) {
        for my $pp (keys %pkg_methods) {
            my $k = decl_key($pp, $method, $rtype);
            return $k if exists $decls{$k};
        }
    }
    # if method name unique across all internal decls
    my @cands;
    for my $d (values %decls) {
        push @cands, $d->{key} if $d->{recv} && $d->{name} eq $method;
    }
    return $cands[0] if @cands == 1;
    # if unique among imported packages
    my %imported_pp;
    for my $path (values %{ $info->{imports} }) {
        $imported_pp{$path} = 1 if $path =~ m{^\Q$MOD/internal\E(/|$)};
    }
    my @scoped;
    for my $d (values %decls) {
        next unless $d->{recv} && $d->{name} eq $method;
        push @scoped, $d->{key} if $imported_pp{$d->{pkgpath}} || pkgpath_from_rel($info->{file}) eq $d->{pkgpath};
    }
    return $scoped[0] if @scoped == 1;
    return undef;
