#!/bin/bash
set -euo pipefail
ROOT=/bench/repo
MOD=github.com/usememos/memos

pkgpath_from_rel() {
  local rel=$1
  [[ $rel == internal/* ]] || return 1
  local dir
  dir=$(dirname "$rel")
  if [[ $dir == internal ]]; then echo "$MOD/internal"; else echo "$MOD/$dir"; fi
}

# Build declarations
> /tmp/decls.tsv
while IFS= read -r f; do
  rel=${f#$ROOT/}
  pp=$(pkgpath_from_rel "$rel") || continue
  while IFS= read -r line; do
    ln=${line%%:*}
    body=${line#*:}
    if [[ $body =~ ^func\ \(([^)]*)\)[[:space:]]+([A-Za-z0-9_]+) ]]; then
      recv="${BASH_REMATCH[1]}"
      name="${BASH_REMATCH[2]}"
      rt=$(echo "$recv" | sed -E 's/.*\*?[[:space:]]*([A-Za-z0-9_.]+).*/\1/' | sed 's/.*\.//')
      sym="($rt).$name"
      echo -e "${pp}\t${rt}\t${name}\t${rel}\t${ln}\t${sym}" >> /tmp/decls.tsv
    elif [[ $body =~ ^func[[:space:]]+([A-Za-z0-9_]+) ]]; then
      name="${BASH_REMATCH[1]}"
      echo -e "${pp}\t\t${name}\t${rel}\t${ln}\t${name}" >> /tmp/decls.tsv
    fi
  done < <(grep -n '^func ' "$f")
done < <(find "$ROOT/internal" -name '*.go')

