> /tmp/imports.tsv
while IFS= read -r f; do
  rel=${f#$ROOT/}
  # crude import extraction
  awk -v file="$rel" '
    /^\s*import \(/ {inimp=1; next}
    inimp && /^\)/ {inimp=0; next}
    inimp {
      if (match($0, /"([^"]+)"/, a)) {
        path=a[1]
        alias=$1
        if (alias ~ /^"/) { split(path, p, "/"); alias=p[length(p)] }
        print file "\t" alias "\t" path
      }
    }
    /^\s*import "/ {
      if (match($0, /"([^"]+)"/, a)) {
        path=a[1]; split(path, p, "/"); alias=p[length(p)]
        print file "\t" alias "\t" path
      }
    }
    /^\s*import [A-Za-z]/ {
      if (match($0, /([A-Za-z0-9_]+)[[:space:]]+"([^"]+)"/, a)) {
        print file "\t" a[1] "\t" a[2]
      }
    }
  ' "$f"
done < <(find "$ROOT" -name '*.go') >> /tmp/imports.tsv

