my ($ROOT, $MOD) = @ARGV;
# load decls
my %decl; # key -> {sym,file,line}
open my $df, '<', '/tmp/decls.tsv' or die $!;
while (<$df>) {
  chomp; my ($pp,$rt,$name,$file,$ln,$sym) = split /\t/, $_, 6;
  my $k = $rt ? "$pp|$rt|$name" : "$pp|$name";
  $decl{$k} = {sym=>$sym, file=>$file, line=>$ln} unless exists $decl{$k};
}

# load imports: file -> alias -> path
my %imp;
open my $if, '<', '/tmp/imports.tsv' or die $!;
while (<$if>) {
  chomp; my ($file,$alias,$path) = split /\t/, $_;
  $imp{$file}{$alias} = $path;
}

# pkgpath from rel
sub pkgpath {
  my ($rel) = @_;
  return '' unless $rel =~ /^internal\//;
  my $dir = $rel; $dir =~ s{/[^/]+$}{};
  return "$MOD/internal" if $dir eq 'internal';
  return "$MOD/$dir";
}

sub strip {
  my ($s) = @_;
  $s =~ s/`(?:\\.|[^`\\])*`//gs;
  $s =~ s/"(?:\\.|[^"\\])*"//gs;
  $s =~ s/'(?:\\.|[^'\\])*'//gs;
  $s =~ s{//.*$}{}gm;
  $s =~ s{/\*.*?\*/}{}gs;
  return $s;
}

my @gos = split /\n/, `find '$ROOT' -name '*.go' 2>/dev/null`;
my %calls; # decl_key -> { sites, callers{}, files{}, nt_sites, nt_callers{}, nt_files{} }

sub bump {
  my ($k, $caller_id, $caller_file, $caller_test) = @_;
  return unless exists $decl{$k};
  $calls{$k}{sites}++;
  $calls{$k}{callers}{$caller_id} = 1;
  $calls{$k}{files}{$caller_file} = 1;
  unless ($caller_test) {
    $calls{$k}{nt_sites}++;
    $calls{$k}{nt_callers}{$caller_id} = 1;
    $calls{$k}{nt_files}{$caller_file} = 1;
  }
}

for my $go (@gos) {
  my $rel = $go; $rel =~ s/^\Q$ROOT\E\/?//;
  open my $fh, '<', $go or next;
  local $/; my $src = <$fh>; close $fh;
  my $clean = strip($src);
  my $is_test = ($rel =~ /_test\.go$/);

  pos($clean)=0;
  while ($clean =~ /^func\s+(?:\(([^)]*)\)\s+)?(\w+)\s*\([^)]*\)\s*(?:\([^)]*\)\s*)?\{/gm) {
    my ($recv_raw, $fname) = ($1, $2);
    my $start = pos($clean)-1;
    my $recv='';
    if (defined $recv_raw && $recv_raw ne '') {
      if ($recv_raw =~ /\*\s*([\w\.]+)/) { $recv=$1 } elsif ($recv_raw =~ /([\w\.]+)\s*$/) { $recv=$1 }
      $recv =~ s/^.*\.//;
    }
    my $caller_id = "$rel|$recv|$fname";
    my $rest = substr($clean, $start);
    my ($depth,$i,$len)=(1,1,length($rest));
    while ($i < $len && $depth > 0) {
      my $c=substr($rest,$i,1);
      $depth++ if $c eq '{'; $depth-- if $c eq '}'; $i++;
    }
    my $body = substr($rest,0,$i);

    # qualified calls alias.Name(
    while ($body =~ /\b([A-Za-z_]\w*)\.([A-Za-z_]\w*)\s*\(/g) {
      my ($al,$fn)=($1,$2);
      next if $fn =~ /^(Bool|String|Int|Int64|Float64|Error|Bytes|Duration|Interface|Uint64|Len|Less|Swap)$/;
      my $path = $imp{$rel}{$al};
      if (defined $path && index($path, "$MOD/internal") == 0) {
        my $k = "$path|$fn";
        bump($k, $caller_id, $rel, $is_test) if exists $decl{$k};
      }
    }

    # same-package bare calls in internal files
    my $pp = pkgpath($rel);
    if ($pp) {
      while ($body =~ /(?:^|[^\w.])([A-Za-z_]\w*)\s*\(/gm) {
        my $fn=$1;
        next if $fn =~ /^(if|for|switch|return|func|go|defer|make|new|len|cap|append|delete|panic|recover|print|println)$/;
        my $k = "$pp|$fn";
        bump($k, $caller_id, $rel, $is_test) if exists $decl{$k};
      }
    }

    # method calls var.Method( with simple type inference
    my %vtypes;
    while ($body =~ /\b(\w+)\s*:?=\s*(?:&|\*)?([\w\.]+)\{/g) {
      my ($v,$t)=($1,$2); $t=~s/^.*\.//; $vtypes{$v}=$t;
    }
    while ($body =~ /\b(\w+)\s*:?=\s*(?:&|\*)?([\w\.]+)\(/g) {
      my ($v,$t)=($1,$2);
      next if $t =~ /^(make|new|append|len|cap|delete|close|panic|recover|print|println)$/;
      $t=~s/^.*\.//; $vtypes{$v}=$t;
    }
    while ($body =~ /(?:^|,|\()\s*(\w+)\s+(?:\*([\w\.]+)|([\w\.]+))/gm) {
      my ($v,$tp,$t)=($1,$2,$3); $t//=$tp; $t=~s/^.*\.//; $vtypes{$v}=$t if $t;
    }
    while ($body =~ /\b(\w+)\.(\w+)\s*\(/g) {
      my ($v,$mn)=($1,$2);
      next if exists $imp{$rel}{$v}; # already handled as package
      my $rt = $vtypes{$v};
      if ($rt) {
        for my $k (keys %decl) {
          bump($k, $caller_id, $rel, $is_test) if $decl{$k} && $k =~ /\|$rt\|$mn$/;
        }
      }
    }
  }
}

my @sorted = sort {
  ($calls{$b}{nt_sites}//0) <=> ($calls{$a}{nt_sites}//0)
    || scalar(keys %{$calls{$b}{nt_callers}//{}}) <=> scalar(keys %{$calls{$a}{nt_callers}//{}})
    || ($calls{$b}{sites}//0) <=> ($calls{$a}{sites}//0)
} keys %decl;

print "=== TOP 50 by non-test call sites (import-resolved + same-package + method inference) ===\n";
my $n=0;
for my $k (@sorted) {
  my $nt = $calls{$k}{nt_sites}//0;
  next unless $nt>0;
  last if $n>=50;
  my $d=$decl{$k};
  my $sites=$calls{$k}{sites}//0;
  my $nc=scalar keys %{$calls{$k}{nt_callers}//{}};
  my $nf=scalar keys %{$calls{$k}{nt_files}//{}};
  my $tc=scalar keys %{$calls{$k}{callers}//{}};
  printf "%s | %s:%d | nt_sites=%d nt_callers=%d nt_files=%d | total_sites=%d total_callers=%d\n",
    $d->{sym}, $d->{file}, $d->{line}, $nt, $nc, $nf, $sites, $tc;
  $n++;
}

my $best = (grep { ($calls{$_}{nt_sites}//0)>0 } @sorted)[0];
if ($best) {
  my $d=$decl{$best};
  print "\nWINNER: $d->{sym} | $d->{file}:$d->{line} | nt_sites=".($calls{$best}{nt_sites}//0).
    " nt_callers=".scalar(keys %{$calls{$best}{nt_callers}//{}})."\n";
}
PERL

SCRIPT
bash /tmp/fanin_full.sh 2>&1

