# Fast comprehensive scan: for each internal decl with unique name in repo, count call sites
perl -Mstrict -Mwarnings <<'PERL'
my $ROOT='/bench/repo';
my @decls;
open my $df,'<','/tmp/decls.tsv' or die;
while(<$df>){
  chomp; my($pp,$rt,$name,$file,$ln,$sym)=split/\t/,$_,6;
  push @decls, {pp=>$pp,rt=>$rt,name=>$name,file=>$file,line=>$ln,sym=>$sym};
}

# count declarations per name repo-wide (all go files) - for ambiguity flag
my %name_decl_count;
for my $d (@decls){
  my $out = `grep -rn '^func \\(\\[^)]*\\) \\?\${name}\\b\\|^func \\?\${name}\\b' '$ROOT' --include='*.go' 2>/dev/null`;
}
# simpler: only use names unique within entire repo internal declarations
my %iname; $iname{$_->{name}}++ for @decls;
my @uniq = grep { $iname{$_->{name}} == 1 } @decls;

my @results;
for my $d (@uniq){
  my $name = $d->{name}; my $sym=$d->{sym};
  my $pat;
  if ($d->{rt}) {
    # method: count .name( as best effort for unique method names
    $pat = qr/\.${name}\s*\(/;
  } else {
    $pat = qr/\b${name}\s*\(/;
  }
  my $nt=0; my $tot=0;
  for my $go (split/\n/, `find '$ROOT' -name '*.go' 2>/dev/null`){
    open my $fh,'<',$go or next; my @lines=<$fh>; close $fh;
    my $rel=$go; $rel=~s/^\Q$ROOT\E\/?//; my $test=($rel=~/_test\.go$/);
    for my $i (0..$#lines){
      next unless $lines[$i] =~ $pat;
      next if $lines[$i] =~ /^\s*func\s/; # skip decl line
      $tot++;
      $nt++ unless $test;
    }
  }
  push @results, {sym=>$sym,file=>"$d->{file}:$d->{line}",nt=>$nt,tot=>$tot,name=>$name,method=>($d->{rt}?1:0)};
}
@results = sort { $b->{nt}<=>$a->{nt} || $b->{tot}<=>$a->{tot} } @results;
print "=== Unique-name internal symbols by non-test call sites ===\n";
for (0..29){ last unless $_ < @results; my $r=$results[$_];
  printf "%s | %s | nt=%d tot=%d%s\n", $r->{sym}, $r->{file}, $r->{nt}, $r->{tot}, ($r->{method}?" [method,.Name heuristic]":""); }
PERL

