use strict;
use warnings;
my @ENTITY = qw(Attachment IdentityProvider Inbox InstanceSetting Memo MemoRelation MemoShare Reaction User UserIdentity UserSetting AuthenticationConfigState);
my %entity_map; $entity_map{$_}=1 for @ENTITY;

my $ROOT = "/bench/repo";
my %type_pkgs;
my %type_files;

find_go_files($ROOT);

sub is_store_layer {
    my ($rel) = @_;
    return $rel =~ m{^store/} || $rel eq "store";
}

sub find_go_files {
    my ($dir) = @_;
    opendir(my $dh, $dir) or return;
    while (my $ent = readdir($dh)) {
        next if $ent =~ /^\./;
        my $path = "$dir/$ent";
        if (-d $path) {
            next if $ent eq ".git" || $ent eq "node_modules" || $ent eq "web";
            find_go_files($path);
        } elsif ($ent =~ /\.go$/) {
            analyze_file($path);
        }
    }
    closedir $dh;
}

sub analyze_file {
    my ($fp) = @_;
    my $rel = $fp; $rel =~ s/^\Q$ROOT\E\/?//;
    return if is_store_layer($rel);

    open my $fh, "<", $fp or return;
    local $/; my $content = <$fh>; close $fh;
    return unless $content =~ /github\.com\/usememos\/memos\/store/;

    my $local = "store";
    if ($content =~ /(\w+)\s+"github\.com\/usememos\/memos\/store"/) {
        $local = $1;
    }

    my $pkg = $fp; $pkg =~ s/\/[^\/]+$//;

    for my $t (@ENTITY) {
        my $pat = qr/\b\Q$local\E\.\Q$t\E\b/;
        if ($content =~ /$pat/) {
            $type_pkgs{$t}{$pkg} = 1;
            $type_files{$t}{$rel} = 1;
        }
    }
}

print "=== RANKING ===\n";
my @sorted = sort { ($type_pkgs{$b}?scalar(keys %{$type_pkgs{$b}}):0) <=> ($type_pkgs{$a}?scalar(keys %{$type_pkgs{$a}}):0) || $a cmp $b } @ENTITY;
for my $t (@sorted) {
    my $n = scalar keys %{$type_pkgs{$t} // {}};
    print "$t: $n packages\n";
    for my $p (sort keys %{$type_pkgs{$t} // {}}) {
        (my $rp = $p) =~ s/^\Q$ROOT\E\/?//;
        print "  - $rp\n";
    }
    print "\n";
}
' /dev/null 2>&1 | head -5

